# Run only in the disposable packaged app generated by packaged_smoke.rb.
require "securerandom"
require "nokogiri"
raise "Production required" unless Rails.env.production?
raise "Consumer loaded source checkout" unless RailsNewadmin::Engine.root.realpath.to_s == File.realpath(ENV.fetch("PACKAGED_ROOT"))
raise "Node unexpectedly available" if system("command -v node >/dev/null 2>&1")
user = identity = nil
begin
  password = SecureRandom.base64(24)
  user = User.create!(email_address: "host-smoke-#{SecureRandom.hex(8)}@example.test", password: password)
  session = ActionDispatch::Integration::Session.new(Rails.application)
  session.host! "www.example.com"
  session.https!
  mount = "/control"
  session.get mount
  raise "Host login redirect failed" unless session.response.status == 302 && URI(session.response.location).path == "/session/new"
  session.get "/session/new"
  raise "Native host form unavailable" unless session.response.status == 200
  token = Nokogiri::HTML(session.response.body).at_css('meta[name="csrf-token"]')["content"]
  session.post "/session", params: { email_address: user.email_address, password: password }, headers: { "X-CSRF-Token" => token }
  raise "Native login failed" unless session.response.status == 302
  session.get mount
  raise "Ordinary host account was admitted" unless session.response.status == 403
  identity = RailsNewadmin::ActorIdentity.create!(**RailsNewadmin::ActorIdentity.key_for(user), active: true, staff: true, superuser: true)
  session.get mount
  raise "Provisioned host account denied" unless session.response.status == 200
  page = Nokogiri::HTML(session.response.body)
  raise "Host logout form missing" unless page.at_css('form[action="/session"][data-turbo="false"] input[name="_method"][value="delete"]')
  css = page.at_css('link[rel="stylesheet"]')["href"]
  session.get "#{mount}/resources/articles/new"
  token = Nokogiri::HTML(session.response.body).at_css('meta[name="csrf-token"]')["content"]
  session.post "#{mount}/resources/articles", params: { record: { title: "Host production smoke", status: "draft" } }, headers: { "X-CSRF-Token" => token }
  raise "Host CRUD failed" unless session.response.status == 303
  event = RailsNewadmin::AuditEvent.order(:id).last
  raise "Wrong audit identity" unless event.actor_type == "User" && event.actor_id == user.id.to_s
  session.get css
  raise "Packaged stylesheet missing" unless session.response.status == 200
  session.get "#{mount}/session/new"
  raise "Builtin login enabled in host mode" unless session.response.status == 404
  session.get mount
  token = Nokogiri::HTML(session.response.body).at_css('meta[name="csrf-token"]')["content"]
  session.delete "/session", headers: { "X-CSRF-Token" => token }
  raise "Host logout failed: HTTP #{session.response.status}, sessions #{user.sessions.count}" unless session.response.status == 303 && user.sessions.empty?
  session.get mount
  raise "Host session survived logout" unless session.response.status == 302 && URI(session.response.location).path == "/session/new"
  puts "Packaged native Rails host login, default deny, identity, CSRF CRUD, audit, logout and compiled assets: passed"
ensure
  if user&.persisted?
    RailsNewadmin::AuditEvent.where(actor_type: "User", actor_id: user.id.to_s).delete_all
    user.destroy!
  end
  identity&.destroy!
  Article.where(title: "Host production smoke").destroy_all
end
